mapper.update:
update outbound_record
status = #{status}, del_flag = #{delFlag}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select o.*, w.name as warehouse_name, s.name as staff_name, , (select string_agg(m.name, ',') from outbound_material om left join material m on om.material_id = m.id where om.outbound_record_id = o.id) as material_names from outbound_record o left join warehouse w on o.warehouse_id = w.id left join staff s on o.staff_id = s.id where o.del_flag = 0
and o.warehouse_id = #{warehouseId}
and o.material_use like concat('%', #{materialUse}, '%')
and o.status = #{status}
and o.outbound_time >= #{startTime}
and o.outbound_time <= #{endTime}
order by o.create_time desc
